def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    if not cwd.startswith('/') or (cwd != '/' and cwd.endswith('/')):
        return None

    link_count = 0
    max_links = 8

    # Start with the initial path
    if path.startswith('/'):
        current = '/'
        components = path[1:].split('/')
    else:
        current = cwd
        components = path.split('/')

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty and '.'
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if current == '/':
                continue
            # Move to parent
            current = current.rsplit('/', 1)[0]
            if current == '':
                current = '/'
            continue

        # Append the component
        if current == '/':
            next_path = '/' + comp
        else:
            next_path = current + '/' + comp

        # Check if it's a symlink
        if next_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[next_path]

            # Parse the target and remaining components
            if target.startswith('/'):
                current = '/'
                target_components = target[1:].split('/')
            else:
                # Target is relative to the directory containing the link
                current = next_path.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
                target_components = target.split('/')

            # Insert remaining components after target components
            components = target_components + components[i:]
            i = 0
        else:
            current = next_path

    # Remove trailing slash (except for '/')
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

